import{_ as a,a as r,c as n,ac as t}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"查找、排序与区间","description":"先判断是否需要排序，再按有序性、稳定性、值域和空间选择查找或排序方法；区间安排、Top K 与合并代价单独定位。","frontmatter":{"title":"查找、排序与区间","description":"先判断是否需要排序，再按有序性、稳定性、值域和空间选择查找或排序方法；区间安排、Top K 与合并代价单独定位。","generated":"consolidation-v2","showdocs":{"topics":[{"id":"algorithms","title":"算法","link":"/topics/algorithms/"},{"id":"go","title":"Go","link":"/topics/go/"}],"kind":"问题与数据结构","scope":"general","audience":"general","group":"原理与设计","summary":"先判断是否需要排序，再按有序性、稳定性、值域和空间选择查找或排序方法；区间安排、Top K 与合并代价单独定位。","status":"active","related":[{"title":"Go 算法与容器实践：遍历、排序、递推与堆","link":"/principles/algorithms/exercises/go-interview-algorithm","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组","link":"/principles/algorithms/exercises/leetcode-arrary","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组 · 两数之和至移除元素","link":"/principles/algorithms/exercises/leetcode-arrary-part-01","kind":"算法推演","scope":"general","audience":"general"},{"title":"Leetcode 数组 · 搜索插入位置至完整入口与预期结果","link":"/principles/algorithms/exercises/leetcode-arrary-part-02","kind":"算法推演","scope":"general","audience":"general"},{"title":"0/1 背包","link":"/principles/algorithms/dp/knapsack-01","kind":"问题与数据结构","scope":"general","audience":"general"}],"prev":{"text":"插入排序","link":"/principles/algorithms/sorting/insertion-sort"},"next":{"text":"堆排序","link":"/principles/algorithms/sorting/heap-sort"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"插入排序","link":"/principles/algorithms/sorting/insertion-sort"},"next":{"text":"堆排序","link":"/principles/algorithms/sorting/heap-sort"}},"headers":[],"relativePath":"principles/algorithms/sorting/algorithms-sorting-general-general.md","filePath":"principles/algorithms/sorting/algorithms-sorting-general-general.md"}'),s={name:"principles/algorithms/sorting/algorithms-sorting-general-general.md"};function i(p,e,o,d,l,c){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="查找、排序与区间" tabindex="-1">查找、排序与区间 <a class="header-anchor" href="#查找、排序与区间" aria-label="Permalink to &quot;查找、排序与区间&quot;">​</a></h1><p>本页按场景选择方法；通过各条目链接阅读完整推演、源码和输出。</p><p>这些 package main 程序应分别保存到独立练习模块（Go 1.22+）；本轮未运行。原地排序会改输入，归并/计数/桶排序返回新结果。数值和分配大小必须落在本机 int 与可用内存范围内，桶宽必须为正；无效输入的返回约定不替代生产 API 校验。</p><table tabindex="0"><thead><tr><th>要解决的问题</th><th>可选方法</th><th>选择前确认</th></tr></thead><tbody><tr><td>只查询少量或无序数据</td><td><a href="#entry-linear-search-d8d0d0ec53">线性查找</a>；有序输入才用<a href="#entry-binary-search-7e63da33a1">二分查找</a></td><td>二分答案还要求可行性单调且上下界覆盖解。</td></tr><tr><td>学习局部交换，或处理小数组、近乎有序数据</td><td><a href="#entry-bubble-sort-2ead6e3442">冒泡排序</a>、<a href="#entry-selection-sort-3f2dbae9c7">选择排序</a>、<a href="#entry-insertion-sort-59b8bbb79e">插入排序</a>、<a href="#entry-shell-sort-2bc9c2de55">希尔排序</a></td><td>插入最坏仍为 O(n²)；选择排序不稳定，希尔性能取决于间隔序列。</td></tr><tr><td>需要保留相等元素的原顺序</td><td><a href="#entry-merge-sort-e42f91858d">归并排序</a></td><td>时间 O(n log n)，需要 O(n) 合并空间。</td></tr><tr><td>比较平均性能与原地排序的时间上界</td><td><a href="#entry-quick-sort-bcf4adabf6">快速排序</a>或<a href="#entry-heap-sort-0c7e3f0c11">堆排序</a></td><td>快排平均 O(n log n)、最坏 O(n²)；堆排序原地且有 O(n log n) 上界，但不稳定。</td></tr><tr><td>已知整数值域、位数或数据分布</td><td><a href="#entry-counting-sort-348b8a1d74">计数排序</a>、<a href="#entry-radix-sort-47aeee633c">基数排序</a>、<a href="#entry-bucket-sort-8263df6e36">桶排序</a></td><td>计数和基数示例只处理非负整数；桶排序效果依赖分布和桶宽。</td></tr><tr><td>只保留最大的 k 个值</td><td><a href="#entry-top-k-b735a2ef4f">Top K 最小堆</a></td><td>时间 O(n log k)；返回堆内部顺序，展示时可能还需排序。</td></tr><tr><td>安排最多活动、合并覆盖范围或降低文件合并成本</td><td><a href="#entry-interval-scheduling-662c8e8176">区间调度</a>、<a href="#entry-merge-intervals-c64ece91b5">区间合并</a>、<a href="#entry-optimal-merge-3681de0e24">最小代价合并</a></td><td>分别按结束时间、起点和当前最小文件选择；端点是否冲突须按业务定义。</td></tr></tbody></table><h2 id="scene-measure-and-find" tabindex="-1">估算成本并选择查找方式 <a class="header-anchor" href="#scene-measure-and-find" aria-label="Permalink to &quot;估算成本并选择查找方式 {#scene-measure-and-find}&quot;">​</a></h2><h3 id="entry-complexity-84d75cf9e5" tabindex="-1">时间与空间复杂度 <a class="header-anchor" href="#entry-complexity-84d75cf9e5" aria-label="Permalink to &quot;时间与空间复杂度 {#entry-complexity-84d75cf9e5}&quot;">​</a></h3><p><span id="输出"></span><span id="示例"></span></p><p><span id="entry-complexity-84d75cf9e5-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/complexity">时间与空间复杂度</a>。</p><p>先确定 n 表示什么，再统计循环或递归会执行多少次。示例只遍历一次切片，所以输入翻倍时工作量大致翻倍；累计变量只占固定空间。 示例时间 O(n)、额外空间 O(1)。</p><p>复杂度描述的是增长趋势，常数开销和真实输入分布仍会影响性能。</p><h3 id="entry-linear-search-d8d0d0ec53" tabindex="-1">线性查找 <a class="header-anchor" href="#entry-linear-search-d8d0d0ec53" aria-label="Permalink to &quot;线性查找 {#entry-linear-search-d8d0d0ec53}&quot;">​</a></h3><p><span id="输出-1"></span><span id="示例-1"></span></p><p><span id="entry-linear-search-d8d0d0ec53-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/linear-search">线性查找</a>。</p><p>从头检查每个元素，第一次相等时返回下标。它不要求预处理或排序，数据很少或只查询一次时常是最简单的选择。 时间 O(n)。</p><p>若在同一大集合上反复查找，可以考虑排序后二分或建立哈希索引。</p><h3 id="entry-binary-search-7e63da33a1" tabindex="-1">二分查找 <a class="header-anchor" href="#entry-binary-search-7e63da33a1" aria-label="Permalink to &quot;二分查找 {#entry-binary-search-7e63da33a1}&quot;">​</a></h3><p><span id="输出-2"></span><span id="示例-2"></span></p><p><span id="entry-binary-search-7e63da33a1-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/binary-search">二分查找</a>。</p><p>维护一个可能包含目标值的半开区间 [l,r)，根据中点与目标的比较缩小一侧。循环结束后还需检查候选下标是否真的匹配。 时间 O(log n)。</p><p>前提是输入按相同规则排序；否则二分的排除逻辑不成立。</p><h3 id="entry-binary-search-answer-ecae88bce4" tabindex="-1">二分答案 <a class="header-anchor" href="#entry-binary-search-answer-ecae88bce4" aria-label="Permalink to &quot;二分答案 {#entry-binary-search-answer-ecae88bce4}&quot;">​</a></h3><p><span id="输出-3"></span><span id="示例-3"></span></p><p><span id="entry-binary-search-answer-ecae88bce4-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/binary-search-answer">二分答案</a>。</p><p>使用前要证明边界覆盖解，并防止不可行时把 hi 误当作有效答案。</p><h2 id="scene-comparison-sort" tabindex="-1">从简单排序比较到归并、快排与堆排序 <a class="header-anchor" href="#scene-comparison-sort" aria-label="Permalink to &quot;从简单排序比较到归并、快排与堆排序 {#scene-comparison-sort}&quot;">​</a></h2><h3 id="entry-insertion-sort-59b8bbb79e" tabindex="-1">插入排序 <a class="header-anchor" href="#entry-insertion-sort-59b8bbb79e" aria-label="Permalink to &quot;插入排序 {#entry-insertion-sort-59b8bbb79e}&quot;">​</a></h3><p><span id="输出-4"></span><span id="示例-4"></span></p><p><span id="entry-insertion-sort-59b8bbb79e-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/insertion-sort">插入排序</a>。</p><p>循环开始时，左侧前缀始终有序；当前值向左寻找位置，并把较大的元素右移。输入接近有序时移动次数很少，因此小数组或排序算法的收尾阶段常会采用它。 最坏时间 O(n²)。</p><p>完全逆序时仍需 O(n²) 次移动。</p><h3 id="entry-bubble-sort-2ead6e3442" tabindex="-1">冒泡排序 <a class="header-anchor" href="#entry-bubble-sort-2ead6e3442" aria-label="Permalink to &quot;冒泡排序 {#entry-bubble-sort-2ead6e3442}&quot;">​</a></h3><p><span id="输出-5"></span><span id="示例-5"></span></p><p><span id="entry-bubble-sort-2ead6e3442-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/bubble-sort">冒泡排序</a>。</p><p>真实项目通常直接使用 sort 包；该算法主要帮助理解局部交换与不变式。</p><h3 id="entry-selection-sort-3f2dbae9c7" tabindex="-1">选择排序 <a class="header-anchor" href="#entry-selection-sort-3f2dbae9c7" aria-label="Permalink to &quot;选择排序 {#entry-selection-sort-3f2dbae9c7}&quot;">​</a></h3><p><span id="输出-6"></span><span id="示例-6"></span></p><p><span id="entry-selection-sort-3f2dbae9c7-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/selection-sort">选择排序</a>。</p><p>在未排序部分找到最小元素，与当前位置交换，然后缩小待处理范围。它始终需要二次方级比较，却只进行线性次数的交换。 时间 O(n²)，交换次数 O(n)。</p><p>交换会改变相等元素的相对顺序，因此这个基本版本不稳定。</p><h3 id="entry-shell-sort-2bc9c2de55" tabindex="-1">希尔排序 <a class="header-anchor" href="#entry-shell-sort-2bc9c2de55" aria-label="Permalink to &quot;希尔排序 {#entry-shell-sort-2bc9c2de55}&quot;">​</a></h3><p><span id="输出-7"></span><span id="示例-7"></span></p><p><span id="entry-shell-sort-2bc9c2de55-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/shell-sort">希尔排序</a>。</p><p>它就地工作且代码不复杂，但最坏性能依赖所选间隔序列，通常不如标准库排序具有明确保证。</p><h3 id="entry-merge-sort-e42f91858d" tabindex="-1">归并排序 <a class="header-anchor" href="#entry-merge-sort-e42f91858d" aria-label="Permalink to &quot;归并排序 {#entry-merge-sort-e42f91858d}&quot;">​</a></h3><p><span id="输出-8"></span><span id="示例-8"></span></p><p><span id="entry-merge-sort-e42f91858d-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/merge-sort">归并排序</a>。</p><p>递归把数组分成两半，分别排序后通过比较两边当前元素完成合并。合并时优先取左侧相等元素可保持稳定性。 时间 O(n log n)、额外空间 O(n)。</p><p>每层总工作为 O(n)，层数为 O(log n)；代价是需要额外的合并空间。</p><h3 id="entry-quick-sort-bcf4adabf6" tabindex="-1">快速排序 <a class="header-anchor" href="#entry-quick-sort-bcf4adabf6" aria-label="Permalink to &quot;快速排序 {#entry-quick-sort-bcf4adabf6}&quot;">​</a></h3><p><span id="输出-9"></span><span id="示例-9"></span></p><p><span id="entry-quick-sort-bcf4adabf6-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/quick-sort">快速排序</a>。</p><p>选择一个基准值，用双指针把较小值移到左侧、较大值移到右侧，再分别递归。分区均衡时性能很好；若基准长期偏向一侧，递归深度和时间会恶化。 平均时间 O(n log n)，最坏 O(n²)。</p><p>工程实现通常加入随机化或深度限制。</p><h3 id="entry-heap-sort-0c7e3f0c11" tabindex="-1">堆排序 <a class="header-anchor" href="#entry-heap-sort-0c7e3f0c11" aria-label="Permalink to &quot;堆排序 {#entry-heap-sort-0c7e3f0c11}&quot;">​</a></h3><p><span id="输出-10"></span><span id="示例-10"></span></p><p><span id="entry-heap-sort-0c7e3f0c11-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/heap-sort">堆排序</a>。</p><p>先自底向上建立最大堆，根节点就是当前最大值。将根与末尾交换后缩小堆，再向下调整新的根，直到全部元素有序。 时间 O(n log n)、额外空间 O(1)。</p><p>它有稳定的 O(n log n) 时间上界且原地排序，但相等元素的顺序不保留。</p><h2 id="scene-sort-known-domain" tabindex="-1">利用值域、位数或分布减少比较 <a class="header-anchor" href="#scene-sort-known-domain" aria-label="Permalink to &quot;利用值域、位数或分布减少比较 {#scene-sort-known-domain}&quot;">​</a></h2><h3 id="entry-counting-sort-348b8a1d74" tabindex="-1">计数排序 <a class="header-anchor" href="#entry-counting-sort-348b8a1d74" aria-label="Permalink to &quot;计数排序 {#entry-counting-sort-348b8a1d74}&quot;">​</a></h3><p><span id="输出-11"></span><span id="示例-11"></span></p><p><span id="entry-counting-sort-348b8a1d74-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/counting-sort">计数排序</a>。</p><p>先统计每个整数值出现的次数，再按值域顺序写回结果。它不通过比较决定先后，因此在值域 k 较小时可优于比较排序。 时间 O(n+k)、空间 O(k)，k 为值域大小。</p><p>示例只支持 0 到 maxValue 的非负整数；值域很大时计数数组会浪费内存。</p><h3 id="entry-radix-sort-47aeee633c" tabindex="-1">基数排序 <a class="header-anchor" href="#entry-radix-sort-47aeee633c" aria-label="Permalink to &quot;基数排序 {#entry-radix-sort-47aeee633c}&quot;">​</a></h3><p><span id="输出-12"></span><span id="示例-12"></span></p><p><span id="entry-radix-sort-47aeee633c-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/radix-sort">基数排序</a>。</p><p>从个位开始，对每一位进行稳定的计数排序，让低位顺序在处理高位时得以保留。位数固定时可获得接近线性的性能。 时间 O(d(n+b))，d 为位数、b 为进制。</p><p>本例基数排序用 exp 表示当前十进制位的权重。处理完一轮后，exp &gt; max/10 表示下一位已经超过最大输入的最高位，应立即退出；这样既避免无意义的继续排序，也防止 exp 乘十溢出。它只接受非负整数，负数需要另行编码。</p><p>示例采用十进制并只处理非负整数；负数或不同类型的键需要额外编码策略。</p><h3 id="entry-bucket-sort-8263df6e36" tabindex="-1">桶排序 <a class="header-anchor" href="#entry-bucket-sort-8263df6e36" aria-label="Permalink to &quot;桶排序 {#entry-bucket-sort-8263df6e36}&quot;">​</a></h3><p><span id="输出-13"></span><span id="示例-13"></span></p><p><span id="entry-bucket-sort-8263df6e36-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/bucket-sort">桶排序</a>。</p><p>根据值与最小值的距离把元素放进不同桶，每个桶内部排序后依次连接。效果依赖数据是否均匀分布以及桶宽是否合适。 分布较均匀时接近线性。</p><p>示例要求 bucketSize 大于零；所有值落入同一桶时优势会消失。</p><h2 id="scene-keep-largest-values" tabindex="-1">只筛选最大的 k 个值 <a class="header-anchor" href="#scene-keep-largest-values" aria-label="Permalink to &quot;只筛选最大的 k 个值 {#scene-keep-largest-values}&quot;">​</a></h2><h3 id="entry-top-k-b735a2ef4f" tabindex="-1">Top K <a class="header-anchor" href="#entry-top-k-b735a2ef4f" aria-label="Permalink to &quot;Top K {#entry-top-k-b735a2ef4f}&quot;">​</a></h3><p><span id="输出-14"></span><span id="示例-14"></span></p><p><span id="entry-top-k-b735a2ef4f-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/top-k">Top K</a>。</p><p>扫描元素时，堆中只保留目前最大的 k 个值，堆顶是这些值中最小的一个。新值若不大于堆顶即可跳过，否则替换堆顶。 时间 O(n log k)。</p><p>示例返回的是堆内部顺序，不保证有序；需要按大小展示时再排序输出。</p><h2 id="scene-schedule-and-merge" tabindex="-1">安排区间与选择合并顺序 <a class="header-anchor" href="#scene-schedule-and-merge" aria-label="Permalink to &quot;安排区间与选择合并顺序 {#scene-schedule-and-merge}&quot;">​</a></h2><h3 id="entry-interval-scheduling-662c8e8176" tabindex="-1">区间调度 <a class="header-anchor" href="#entry-interval-scheduling-662c8e8176" aria-label="Permalink to &quot;区间调度 {#entry-interval-scheduling-662c8e8176}&quot;">​</a></h3><p><span id="输出-15"></span><span id="示例-15"></span></p><p><span id="entry-interval-scheduling-662c8e8176-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/interval-scheduling">区间调度</a>。</p><p>把活动按结束时间排序，优先选择最早结束且不与上一个活动冲突的区间。较早结束会给后续活动留下最多可用空间，这可用交换论证证明最优。 目标是最多可安排的活动数。</p><p>示例把区间视为允许端点相接；是否相接算冲突须按业务定义。</p><h3 id="entry-merge-intervals-c64ece91b5" tabindex="-1">区间合并 <a class="header-anchor" href="#entry-merge-intervals-c64ece91b5" aria-label="Permalink to &quot;区间合并 {#entry-merge-intervals-c64ece91b5}&quot;">​</a></h3><p><span id="输出-16"></span><span id="示例-16"></span></p><p><span id="entry-merge-intervals-c64ece91b5-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/merge-intervals">区间合并</a>。</p><p>按起点排序后，只需和当前合并区间比较：若重叠就扩展终点，否则把新区间放进结果。排序保证后续区间不可能回到已结束区间的左侧。 时间 O(n log n)。</p><p>示例会原地排序输入切片；若调用方需要保留原顺序，应先复制。</p><h3 id="entry-optimal-merge-3681de0e24" tabindex="-1">最小代价合并 <a class="header-anchor" href="#entry-optimal-merge-3681de0e24" aria-label="Permalink to &quot;最小代价合并 {#entry-optimal-merge-3681de0e24}&quot;">​</a></h3><p><span id="输出-17"></span><span id="示例-17"></span></p><p><span id="entry-optimal-merge-3681de0e24-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/algorithms/sorting/optimal-merge">最小代价合并</a>。</p><p>示例反复排序，实际处理大量文件时可换成最小堆。</p><h2 id="review-exercise" tabindex="-1">静态自检 <a class="header-anchor" href="#review-exercise" aria-label="Permalink to &quot;静态自检 {#review-exercise}&quot;">​</a></h2><p>预测 RadixSort 对 {最大int,0,10} 的结果，以及最后一轮为何必须先判断再 exp*=10。提示：最后有效十进制位之后无需继续。</p><details class="details custom-block"><summary>参考解法</summary><p>应升序为 {0,10,最大int}；当 exp &gt; max/10 时已处理最高位，直接结束，避免下一次乘十溢出造成错误位数或异常循环。此结论为静态推导，修改后的示例未执行。</p></details>',117)])])}const g=a(s,[["render",i]]);export{b as __pageData,g as default};
